{
  "id": "20spo-agent-001-add",
  "brandColor": "#007ee5",
  "icon": "https://conn-afd-prod-endpoint-bmc9bqahasf3grgk.b01.azurefd.net/v1.0.1769/1.0.1769.4352/sharepointonline/icon.png",
  "isTrigger": false,
  "operationName": "agent-add",
  "operationDefinition": {
    "type": "Scope",
    "actions": {
      "ServerRelativeWebUrl": {
        "type": "Compose",
        "inputs": "@{replace(concat(uriPath('{{SITE_URL}}'), '/'), '//', '/')}",
        "runAfter": {},
        "metadata": {
          "operationMetadataId": "a1b2c3d4-0010-4000-8000-000000000004"
        }
      },
      "EnsureSiteAssetsLibrary": {
        "type": "OpenApiConnection",
        "inputs": {
          "host": {
            "connectionName": "shared_sharepointonline",
            "operationId": "HttpRequest",
            "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
          },
          "parameters": {
            "dataset": "{{SITE_URL}}",
            "parameters/method": "POST",
            "parameters/uri": "_api/web/lists/EnsureSiteAssetsLibrary()",
            "parameters/headers": {
              "Accept": "application/json",
              "Content-Type": "application/json;charset=utf-8"
            }
          },
          "authentication": {
            "type": "Raw",
            "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
          }
        },
        "runAfter": {
          "ServerRelativeWebUrl": [
            "Succeeded"
          ]
        },
        "metadata": {
          "operationMetadataId": "a1b2c3d4-0010-4000-8000-000000000001"
        }
      },
      "EnsureCopilotFolder": {
        "type": "OpenApiConnection",
        "inputs": {
          "host": {
            "connectionName": "shared_sharepointonline",
            "operationId": "HttpRequest",
            "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
          },
          "parameters": {
            "dataset": "{{SITE_URL}}",
            "parameters/method": "POST",
            "parameters/uri": "_api/web/GetFolderByServerRelativePath(DecodedUrl='@{outputs('ServerRelativeWebUrl')}SiteAssets')/AddSubFolderUsingPath(DecodedUrl='Copilots')",
            "parameters/headers": {
              "Accept": "application/json",
              "Content-Type": "application/json;charset=utf-8"
            }
          },
          "authentication": {
            "type": "Raw",
            "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
          }
        },
        "runAfter": {
          "EnsureSiteAssetsLibrary": [
            "Succeeded"
          ]
        },
        "metadata": {
          "operationMetadataId": "a1b2c3d4-0010-4000-8000-000000000002"
        }
      },
      "AddAgentFile": {
        "type": "OpenApiConnection",
        "inputs": {
          "host": {
            "connectionName": "shared_sharepointonline",
            "operationId": "HttpRequest",
            "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
          },
          "parameters": {
            "dataset": "{{SITE_URL}}",
            "parameters/method": "POST",
            "parameters/uri": "_api/web/GetFolderByServerRelativePath(DecodedUrl='@{outputs('ServerRelativeWebUrl')}SiteAssets/Copilots')/Files/AddUsingPath(DecodedUrl='{{AGENT_NAME}}.agent',EnsureUniqueFileName=true,AutoCheckoutOnInvalidData=true)",
            "parameters/headers": {
              "Accept": "application/json",
              "Content-Type": "application/json;charset=utf-8"
            },
            "parameters/body": "{\n  \"schemaVersion\": \"0.2.0\",\n  \"customCopilotConfig\": {\n    \"conversationStarters\": {\n      \"conversationStarterList\": [],\n      \"welcomeMessage\": {\n        \"text\": \"{{WELCOME_MESSAGE}}\"\n      }\n    },\n    \"gptDefinition\": {\n      \"name\": \"{{AGENT_NAME}}\",\n      \"description\": \"{{AGENT_DESCRIPTION}}\",\n      \"instructions\": \"{{AGENT_INSTRUCTIONS}}\",\n      \"capabilities\": [\n        {\n          \"name\": \"OneDriveAndSharePoint\",\n          \"items_by_sharepoint_ids\": [],\n          \"items_by_url\": []\n        }\n      ]\n    },\n    \"icon\": \"\"\n  }\n}"
          },
          "authentication": {
            "type": "Raw",
            "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
          }
        },
        "runAfter": {
          "EnsureCopilotFolder": [
            "Succeeded",
            "Failed"
          ]
        },
        "metadata": {
          "operationMetadataId": "a1b2c3d4-0010-4000-8000-000000000003"
        }
      }
    },
    "runAfter": {},
    "metadata": {
      "operationMetadataId": "a1b2c3d4-0010-4000-8000-000000000000"
    },
    "description": "Creates a SharePoint agent (.agent file) in SiteAssets/Copilots. Ensures the Site Assets library and Copilots folder exist first. Works for /sites, /teams and root sites."
  }
}

{
  "id": "20spo-branding-001-update",
  "brandColor": "#007ee5",
  "icon": "https://conn-afd-prod-endpoint-bmc9bqahasf3grgk.b01.azurefd.net/v1.0.1769/1.0.1769.4352/sharepointonline/icon.png",
  "isTrigger": false,
  "operationName": "web-update-branding",
  "operationDefinition": {
    "type": "OpenApiConnection",
    "inputs": {
      "host": {
        "connectionName": "shared_sharepointonline",
        "operationId": "HttpRequest",
        "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
      },
      "parameters": {
        "dataset": "{{SITE_URL}}",
        "parameters/method": "POST",
        "parameters/uri": "_api/web",
        "parameters/headers": {
          "Accept": "application/json;odata=nometadata",
