{
  "id": "20spo-search-001-query",
  "brandColor": "#007ee5",
  "icon": "https://conn-afd-prod-endpoint-bmc9bqahasf3grgk.b01.azurefd.net/v1.0.1769/1.0.1769.4352/sharepointonline/icon.png",
  "isTrigger": false,
  "operationName": "search-query",
  "operationDefinition": {
    "type": "OpenApiConnection",
    "inputs": {
      "host": {
        "connectionName": "shared_sharepointonline",
        "operationId": "HttpRequest",
        "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
      },
      "parameters": {
        "dataset": "{{SITE_URL}}",
        "parameters/method": "GET",
        "parameters/uri": "_api/search/query?querytext='{{QUERY_TEXT}}'&rowlimit={{ROW_LIMIT}}&startrow={{START_ROW}}&selectproperties='{{SELECT_PROPERTIES}}'&trimduplicates=false",
        "parameters/headers": {
          "Accept": "application/json;odata=nometadata",
          "Content-Type": "application/json;charset=utf-8"
        }
      },
      "authentication": {
        "type": "Raw",
        "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
      }
    },
    "runAfter": {},
    "description": "Runs a SharePoint Search query. QUERY_TEXT is KQL (URL-encode spaces), e.g. FileType:docx or ContentTypeId:0x0101*. SELECT_PROPERTIES is comma-separated, e.g. Title,Path,FileType. Use START_ROW with ROW_LIMIT for paging.",
    "metadata": {
      "operationMetadataId": "a1b2c3d4-0062-4000-8000-000000000001"
    }
  }
}
